class Pipi:

    def __init__(self):
        self.x = 64
        self.y = 64
        self.estado = Parado(self)

    def actualizar(self):
        self.estado.actualizar()



class Estado:

    def __init__(self, pipi):
        self.pipi = pipi

class Parado(Estado):

    def actualizar(self):
        dibujar(1, self.pipi.x, self.pipi.y)

        if izquierda or derecha:
            self.pipi.estado = Camina(self.pipi)

class Camina(Estado):

    def actualizar(self):
        dibujar([0, 0, 0, 0, 0, 1, 1, 1, 1], self.pipi.x, self.pipi.y)

        if izquierda:
            self.pipi.x -= 1
        elif derecha:
            self.pipi.x += 1
        else:
            self.pipi.estado = Parado(self.pipi)


